    "intro": "ऋग्वेद का प्रथम मण्डल 'शतर्चिन् मण्डल' कहलाता है, क्योंकि इसके द्रष्टा अधिकांश ऋषियों ने सौ या सौ से अधिक ऋचाओं का साक्षात्कार किया है। इसमें कुल १९१ सूक्त, २४ अनुवाक तथा २,००६ मंत्र हैं। यह मण्डल समस्त वैदिक वांग्मय का आदि द्वार है, जिसका प्रारंभ जगत-प्रसिद्ध 'अग्नि सूक्त' (१.१ — 'अग्निमीळे पुरोहितं') से होता है। इसमें शुनःशेप आख्यान, इंद्र-वृत्र संग्राम (१.३२), विश्वेदेवा शांति सूक्त (१.८९ — 'आ नो भद्राः क्रतवो यन्तु विश्वतः'), सूर्य सूक्त (१.११५), तथा महर्षि दीर्घतमस का अत्यंत गूढ़ दार्शनिक 'अस्य वामस्य सूक्त' (१.१६४) समाहित हैं, जिसमें 'एकं सद् विप्रा बहुधा वदन्ति' तथा 'द्वा सुपर्णा सयुजा सखाया' जैसे अमर वैदिक सिद्धांत प्रकट हुए हैं।",
