    "intro": "ऋग्वेद का अष्टम मण्डल वैदिक साहित्य में 'कण्व मण्डल' एवं 'प्रगाथ मण्डल' के नाम से विख्यात है। इस मण्डल में कुल १०३ सूक्त, १० अनुवाक तथा १,७१६ मंत्र हैं। इसमें ९२ मुख्य सूक्तों के अतिरिक्त ११ अत्यंत पवित्र 'खिल सूक्त' (वालखिल्य सूक्त — ८.४९ से ८.५९, कुल ८० मंत्र) समाहित हैं। यह मण्डल सामवेद की संगीतात्मक ऋचाओं का मुख्य उद्गम स्रोत है, क्योंकि इसके अधिकांश मंत्र 'प्रगाथ' छंद (बृहती + सतोबृहती) में निबद्ध हैं, जिन्हें सामगान में उद्गाताओं द्वारा विशेष स्तोभों के साथ गाया जाता है। इस मण्डल में इंद्र, अग्नि, अश्विनीकुमार, वरुण, मरुत, आदित्य तथा ज्ञान-दान की ऐतिहासिक 'दानस्तुतियाँ' प्रचुरता से उपलब्ध हैं।",
