    "primaryMantra": {
      "sanskrit": "ॐ भूर्भुवः॒ स्वः॒।\nतत्स॑वि॒तुर्वरे॑ण्यं॒ भर्गो॑ दे॒वस्य॑ धीमहि।\nधियो॒ यो नः॑ प्रचो॒दया॑त्॥",
      "ref": "ऋग्वेद ३.६२.१० (सस्वर गायत्री महामंत्र)",
      "translation": "हम उस प्राणस्वरूप (भूः), दुःखनाशक (भुवः), सुखस्वरूप (स्वः), सृष्टिकर्ता प्रकाशमान सविता देव के वरण करने योग्य सर्वश्रेष्ठ पापनाशक तेज का ध्यान करते हैं; वह परमात्मा हमारी बुद्धियों को सन्मार्ग में निरंतर प्रेरित करे।"
    },
    "deitiesSymbols": "सविता देव (सृष्टि-सूर्य), गायत्री (प्रातः), सावित्री (माध्याह्न), सरस्वती (सायं), २४ मुद्राएँ।",
    "traditionPlaces": "त्रिकाल संध्या, उपनयन संस्कार, समस्त वैदिक आश्रम व गुरुकुल।",
    "vidhiUsage": "दैनिक त्रिकाल संध्या (प्रातः, मध्याह्न, सायं) में न्यूनतम १०८ बार जप, गायत्री हवन एवं जप-साधना।",
    "traditionsDifferences": "ऋग्वेद में मूल मंत्र 'तत्सवितुर्वरेण्यं...' से प्रारंभ होता है; यजुर्वेद एवं तैत्तिरीय आरण्यक में 'ॐ भूर्भुवः स्वः' (महाव्याहृतियाँ) संयुक्त होकर इसका पूर्ण स्वरूप बना।",
