    "intro": "महामृत्युंजय मंत्र ऋग्वेद के सप्तम मण्डल का ५९वें सूक्त का १२वाँ मंत्र है (७.५९.१२)। इसके ऋषि ब्रह्मर्षि वसिष्ठ (एवं मार्कण्डेय परंपरा) हैं, देवता 'त्र्यम्बक रुद्र' (भगवान शिव) हैं और छंद अनुष्टुप् है। यह सनातन धर्म का परम संजीवनी महामंत्र है जो साधक को अकाल मृत्यु, असाध्य रोगों, भय और सांसारिक बंधनों से मुक्त कर अमृतत्व (मोक्ष) प्रदान करता है।",
