      "ref": "ऋग्वेद ७.५९.१२ (महामृत्युंजय संजीवनी मंत्र)",
      "translation": "हम त्रिनेत्रधारी, सुगंधित और समस्त जगत का पोषण करने वाले भगवान शिव की वंदना करते हैं। जिस प्रकार पका हुआ खरबूजा अपनी बेल के बंधन से सहज ही मुक्त हो जाता है, उसी प्रकार हम मृत्यु व संसार-बंधन से मुक्त हों, किंतु अमरता (मोक्ष) से कभी विमुख न हों।"
