    "intro": "ऋग्वेद की बाष्कल शाखा महर्षि बाष्कल (पैल के शिष्य) द्वारा प्रवर्तित शाखा है। शाकल शाखा के १०२८ सूक्तों की तुलना में बाष्कल संहिता में खिल सूक्तों की संख्या भिन्न थी (इसमें ८ विशिष्ट खिल सूक्त माने गए थे)। यद्यपि इसकी मूल संहिता आज पूर्ण रूप से स्वतंत्र रूप से उपलब्ध नहीं है, तथापि इसके खिल-पाठ, बाष्कल आरण्यक एवं 'बाष्कल उपनिषद्' (जिसमें इंद्र और मेधातिथि का संवाद है) के महत्वपूर्ण अंश वैदिक शोध में अत्यंत मूल्यवान माने जाते हैं।",
