    "intro": "पुरुष सूक्त ऋग्वेद के दशम मण्डल का ९०वाँ सूक्त है। इसमें संपूर्ण १६ ऋचाएँ हैं। इसके ऋषि नारायण हैं और देवता विराट पुरुष हैं। यह सूक्त संपूर्ण ब्रह्मांड को एक विराट चेतन पुरुष के रूप में देखता है, जिससे समस्त खगोलीय पिण्ड, वेद, छंद, ऋतुएँ और मानव समाज का प्रादुर्भाव हुआ है। यह वैश्विक एकता और सर्वात्मभाव का सर्वोच्च वैदिक उद्घोष है।",
