    "traditionPlaces": "मिथिला (विदेह), कोसल, कुरु-पांचाल और गंडकी-गंगा संगम। प्रसिद्ध 'विदेह माथव' की कथा में वैदिक संस्कृति का पूर्व दिशा में विस्तार वर्णित है।",
    "vidhiUsage": "अग्निहोत्र, दर्शपूर्णमास, चातुर्मास्य, अग्निचयन (१०,८०० इष्टिका), राजसूय, अश्वमेध और पुरुषमेध।",
    "traditionsDifferences": "माध्यन्दिन शाखा में १४ काण्ड और १०० अध्याय हैं, जबकि काण्व शाखा में १७ काण्ड और १०४ अध्याय हैं। इसका अंतिम १४वाँ काण्ड ही साक्षात् 'बृहदारण्यक उपनिषद' है।",
