    "intro": "तैत्तिरीय आरण्यक कृष्ण यजुर्वेद का १० प्रपाठकों में विभक्त अत्यंत पावन आरण्यक ग्रंथ है। इसके प्रथम प्रपाठक को 'अरुण प्रश्न' कहा जाता है, जिसमें १३०+ मंत्रों में सूर्य नमस्कार और आरोग्य-उपासना का वर्णन है। इसके ७वें, ८वें और ९वें प्रपाठक मिलकर प्रसिद्ध 'तैत्तिरियोपनिषद्' (शिक्षावल्ली, ब्रह्मानन्दवल्ली, भृगुवल्ली) का निर्माण करते हैं, तथा १०वाँ प्रपाठक 'महानारायणोपनिषद्' कहलाता है।",
