    "traditionPlaces": "दक्षिण भारत की समस्त वैदिक पाठशा hisलाएँ और संध्यावंदन परंपरा।",
    "vidhiUsage": "नित्य सूर्य नमस्कार, अरुण केतुक चयन, संध्यावंदन, दीक्षांत उपदेश और संन्यास संस्कार।",
