    "intro": "तैत्तिरीय संहिता कृष्ण यजुर्वेद की सर्वाधिक विस्तृत, सुरक्षित और अखंड परंपरा वाली संहिता है। इसके आचार्य महर्षि तित्तिरि हैं। इसमें कुल ७ काण्ड (अष्टक), ४४ प्रपाठक, ६५१ अनुवाक और २,१९८ मंत्र हैं। इसमें मंत्र और उनकी व्याख्या (ब्राह्मण भाग) आपस में गुंथे हुए हैं। प्रसिद्ध 'श्री रुद्रम्' (चतुर्थ काण्ड — नमकम् एवं चमकम्), अग्निचयन (पक्षी के आकार की ५ परतों वाली वेदी), वाजपेय, राजसूय और दर्शपूर्णमास के समस्त गूढ़ याज्ञिक विधान इसी संहिता में संरक्षित हैं।",
    "etymology": [
      {
        "term": "तैत्तिरीय",
        "meaning": "तित्तिरि पक्षी का रूप धारण कर महर्षि याज्ञवल्क्य द्वारा त्यक्त यजुर्वेद मंत्रों को ग्रहण करने वाले शिष्यों की परंपरा।"
      },
      {
        "term": "अग्निचयन",
        "meaning": "१,०८० ईंटों द्वारा गरुड़/श्येन पक्षी के आकार में स्वर्गीय वेदी का निर्माण।"
      }
    ],
    "shastricBase": "तैत्तिरीय संहिता काण्ड १ से ७, सायण कृत माधवीय वेदार्थप्रकाश, बौधायन एवं आपस्तंब श्रौतसूत्र।",
    "sourceMeta": {
      "grantha": "कृष्ण यजुर्वेद (Yajurveda)",
      "shakha": "तैत्तिरीय शाखा",
      "kanda": "७ काण्ड (४४ प्रपाठक • ६५१ अनुवाक)",
      "anuvaka": "२,१९८ मंत्र/कंडिकाएँ",
      "rishi": "महर्षि तित्तिरि, आपस्तंब, बौधायन",
      "devata": "अग्नि, रुद्र, सोम, प्रजापति, इंद्र, सविता"
    },
    "primaryMantra": {
      "sanskrit": "इ॒षे त् Nameो॒र्जे त्वा॑ वा॒यव॑ स्थ दे॒वो वः॑ सवि॒ता प्रार्प॑यतु॒ श्रेष्ठ॑तमाय॒ कर्म॑णे।\n\nनमस्ते॑ रुद्र म॒न्यव॑ उ॒तो त॒ इष॑वे॒ नमः॑।\nबा॒हुभ्या॑मु॒त ते॒ नमः॑॥",
      "ref": "तैत्तिरीय संहिता १.१.१ एवं ४.५.१ (श्री रुद्रम् प्रथम अनुवाक)",
      "translation": "हे पलाश की शाखा! अन्न की प्राप्ति के लिए और बल संवर्धन के लिए मैं तुम्हारा स्पर्श करता हूँ। तुम वायु के समान गतिशील हो; सविता देव तुम्हें सर्वश्रेष्ठ यज्ञ-कर्म के लिए प्रेरित करें। हे रुद्र भगवान! आपके क्रोध को नमस्कार है, आपके बाण को नमस्कार है और आपकी दोनों भुजाओं को बारंबार नमस्कार है।"
    },
    "deitiesSymbols": "श्री रुद्र (चतुर्थ काण्ड के नमकम्-चमकम् के अधिष्ठाता), श्येन चिति (उड़ान भरता बाज जो यजमान को स्वर्ग ले जाता है), पञ्चाग्नि।",
    "traditionPlaces": "दक्षिण भारत (तमिलनाडु, आंध्र प्रदेश, कर्नाटक, केरल) जहाँ आज भी तैत्तिरीय शाखा का अखंड सस्वर पाठ जीवित है।",
    "vidhiUsage": "सोमयाग, अतिरात्र, अग्निचयन, रुद्र होम, और नित्य वेद स्वाध्याय।",
    "traditionsDifferences": "शुक्ल यजुर्वेद में जहाँ मंत्र और ब्राह्मण भाग अलग-अलग हैं (संहिता और शतपथ), वहीं तैत्तिरीय संहिता में दोनों एक साथ मिले हुए हैं।",
    "historyResearch": "आर्थर बेरिडेल कीथ (A.B. Keith) ने हार्वर्ड ओरिएंटल सीरीज (खंड १८-१९) में इसका प्रामाणिक अनुवाद प्रस्तुत किया। दक्षिण भारत के वैदिक पाठकों ने सहस्रों वर्षों से इसके उदात्त-अनुदात्त स्वरों को अक्षुण्ण रखा है।",
