    "intro": "बृहदारण्यकोपनिषद् आकार और दर्शन दोनों दृष्टियों से उपनिषदों में विशालतम (बृहत्) है। यह शतपथ ब्राह्मण के १४वें काण्ड का अंतिम भाग है। इसमें ६ प्रपाठक हैं। यजुर्वेद का प्रसिद्ध महावाक्य **'अहं ब्रह्मास्मि' (I am Brahman)** और अमर शांति प्रार्थना **'असतो मा सद्गमय तमसो मा ज्योतिर्गमय'** इसी उपनिषद में है। इसमें महर्षि याज्ञवल्क्य, मैत्रेयी और गार्गी का अद्वितीय दार्शनिक संवाद है।",
