    "intro": "कठोपनिषद् कृष्ण यजुर्वेद की कठ शाखा का सर्वाधिक लोकप्रिय, दार्शनिक एवं प्रामाणिक उपनिषद है। इसमें २ अध्याय और प्रत्येक अध्याय में ३-३ वल्लियाँ (कुल ६ वल्लियाँ और ११९ मंत्र) हैं। यह उपनिषद बालक नचिकेता की तीव्र आत्म-जिज्ञासा तथा मृत्यु के देवता 'यमराज' द्वारा दिए गए गूढ़ आत्मज्ञान का अमर संवाद है। स्वामी विवेकानंद का प्रसिद्ध उद्घोष 'उत्तिष्ठत जाग्रत प्राप्य वरान्निबोधत' (उठो, जागो और ध्येय प्राप्ति तक रुको मत) इसी उपनिषद (१.३.१४) का महामंत्र है।",
    "etymology": [
      {
        "term": "कठोपनिषद्",
        "meaning": "महर्षि वैशम्पायन के शिष्य आचार्य कठ द्वारा प्रवर्तित ज्ञान-परंपरा।"
      },
      {
        "term": "नचिकेता",
        "meaning": "न चिकेत इति नचिकेता — जो सांसारिक नश्वर भोगों से कभी संतुष्ट नहीं होता, केवल शाश्वत सत्य का अन्वेषक है।"
      },
      {
        "term": "श्रेयस् व प्रेयस्",
        "meaning": "श्रेयस् (कल्याणकारी आत्ममार्ग) और प्रेयस् (क्षणिक इंद्रिय सुख का मार्ग)।"
      }
    ],
    "shastricBase": "कठोपनिषद् १.१ से २.३, तैत्तिरीय ब्राह्मण ३.११.८, आदि शंकराचार्य भाष्य।",
    "sourceMeta": {
      "grantha": "कृष्ण यजुर्वेद (Yajurveda)",
      "shakha": "कठ शाखा",
      "kanda": "२ अध्याय • ६ वल्लियाँ (११९ मंत्र)",
      "rishi": "आचार्य कठ, यमराज (उपदेशक), नचिकेता (जिज्ञासु)",
      "devata": "प्रत्यगात्मा, परब्रह्म, ॐकार"
    },
    "primaryMantra": {
      "sanskrit": "उत्ति॑ष्ठत॒ जाग्र॑त प्राप्य॒ वरा॑न्निबो॑धत।\nक्षु॒रस्य॒ धारा॑ निशि॒ता दु॑रत्य॒या दु॒र्गं पथ॒स्तत्क॒वयो॑ वदन्ति॥\n\nन जाय॑ते म्रिय॑ते वा विप॒श्चिन्नायं॑ कुत॑श्चिन्न ब॒भूव॒ कश्चि॑त्।\nअजो॑ नि॒त्यः शाश्व॑तोऽयं पु॒राणो॒ न ह॑न्यते हन्य॒माने॑ शरी॑रे॥",
      "ref": "कठोपनिषद् १.३.१४ एवं १.२.१८",
      "translation": "उठो! जागो! और श्रेष्ठ महापुरुषों की संगति पाकर आत्मज्ञान को प्राप्त करो। ज्ञानीजन कहते हैं कि आत्म-साक्षात्कार का मार्ग छुरे की तीक्ष्ण धार पर चलने के समान अत्यंत दुर्गम है। यह ज्ञानी आत्मा न कभी जन्म लेती है और न कभी मरती है; यह अजन्मा, नित्य, शाश्वत और पुरातन है। शरीर के नष्ट होने पर भी इसका विनाश नहीं होता।"
    },
    "deitiesSymbols": "रथ रूपक (१.३.३-४: शरीर = रथ, बुद्धि = सारथी, मन = लगाम, इंद्रियाँ = अश्व, विषय = मार्ग, आत्मा = रथी), ॐकार (परम आलंबन), अंगुष्ठमात्र पुरुष (हृदय में स्थित चैतन्य)।",
    "traditionPlaces": "कठ गुरुकुल, यमराज का दिव्य सभा-भवन, प्राचीन आर्यावर्त।",
    "vidhiUsage": "संन्यास दीक्षा, आत्म-चिंतन, प्राणायाम, और ॐकार की एकाग्र उपासना।",
    "traditionsDifferences": "कठोपनिषद् में 'श्रेयस्' (कल्याणकारी सत्य) और 'प्रेयस्' (सांसारिक आकर्षण) का जो सुस्पष्ट विभाजन है, वह अन्यत्र दुर्लभ है।",
    "historyResearch": "आदि शंकराचार्य, मध्वाचार्य और रामानुजाचार्य ने इस पर विशद भाष्य लिखे। स्वामी विवेकानंद ने पाश्चात्य जगत में कठोपनिषद् के नचिकेता चरित्र को आत्म-विश्वास का सर्वोच्च आदर्श बताया।",
