    "intro": "शिवसंकल्प सूक्त शुक्ल यजुर्वेद की माध्यन्दिन शाखा के ३४वें अध्याय के प्रथम ६ मंत्रों का समूह है। यह उपनिषद तुल्य वैदिक मनोविज्ञान का सर्वोत्कृष्ट ग्रंथ है। इसमें मानव मन की असीम गतिशीलता, अमर ज्योति और अंतःकरण की शक्तियों का विश्लेषण करते हुए प्रत्येक मंत्र के अंत में प्रार्थना की गई है—'तन्मे मनः शिवसङ्कल्पमस्तु' (मेरा वह मन कल्याणकारी, पवित्र और शुभ संकल्पों से युक्त बने)।",
    "etymology": [
      {
        "term": "शिवसंकल्प",
        "meaning": "शिवः (कल्याणकारी, मंगलमय) + संकल्पः (दृढ़ विचार व निश्चय) — मन के शुभ विचार।"
      },
      {
        "term": "ज्योतिषां ज्योतिः",
        "meaning": "इंद्रियरूपी समस्त ज्योतियों को प्रकाशित करने वाली मन की मूल ज्योति।"
      }
    ],
    "shastricBase": "शुक्ल यजुर्वेद वाजसनेयि माध्यन्दिन संहिता ३४.१-६, सायण भाष्य, महीधर भाष्य।",
    "sourceMeta": {
      "grantha": "शुक्ल यजुर्वेद (Yajurveda)",
      "shakha": "माध्यन्दिन / काण्व शाखा",
      "kanda": "अध्याय ३४ (मंत्र १ - ६)",
      "anuvaka": "६ मंत्र",
      "rishi": "महर्षि याज्ञवल्क्य परंपरा / भौम",
      "devata": "मन (अंतःकरण चैतन्य)",
      "chandas": "त्रिष्टुप्"
    },
    "primaryMantra": {
      "sanskrit": "यज्जाग्र॑तो दू॒रमु॒दैति॒ दैवं॒ तदु॑ सु॒प्तस्य॒ तथै॒वेति॑।\nदू॒र॒ङ्ग॒मं ज्योति॑षां॒ ज्योति॒रेकं॒ तन्मे॒ मनः॑ शि॒वस॑ङ्क॒ल्पम॑स्तु॥\n\nयेने॒दं भू॒तं भुव॑नं भवि॒ष्यत् परि॑गृहीतम॒मृते॑न॒ सर्व॑म्।\nयेन॑ य॒ज्ञस्ता॒यते॑ स॒प्तहो॑ता॒ तन्मे॒ मनः॑ शि॒वस॑ङ्क॒ल्पम॑स्तु॥",
      "ref": "शुक्ल यजुर्वेद ३४.१ एवं ३४.४ (शिवसंकल्प सूक्त)",
      "translation": "जो जाग्रत अवस्था में बहुत दूर-दूर तक चला जाता है और सुप्त (स्वप्न) अवस्था में भी उसी प्रकार दूरगामी रहता है; जो दिव्य गुणों से युक्त, अत्यधिक गतिशील और समस्त इंद्रियों का एकमात्र प्रकाशक है—मेरा वह मन कल्याणकारी एवं शुभ संकल्पों वाला बने। जिस अमर मन द्वारा त्रिकालवर्ती (भूत, वर्तमान, भविष्य) समस्त जगत ग्रहण किया जाता है, और जिसके द्वारा सात होताओं वाला ज्ञान-यज्ञ संपन्न होता है—मेरा वह मन शिव-संकल्प से युक्त हो।"
    },
    "deitiesSymbols": "मन (चैतन्य रथ), रथ-नाभि में आरे (जैसे पहिये की नाभि में तीलियाँ जुड़ी होती हैं, वैसे ही समस्त वेद-ज्ञान मन में प्रतिष्ठित है), सुषुम्ना।",
    "traditionPlaces": "समस्त यजुर्वेदीय गुरुकुल, नित्य प्रातः संध्या उपासना।",
    "vidhiUsage": "मनोविकार निवारण, ध्यान से पूर्व मन की शुद्धि, रुद्राभिषेक का प्रथम अध्याय, और मानसिक शांति पाठ।",
    "traditionsDifferences": "रुद्राष्टाध्यायी के प्रथम अध्याय के रूप में उत्तर भारत के समस्त शैव व स्मार्त अनुष्ठानों में इसका पाठ अनिवार्य है।",
    "historyResearch": "आधुनिक न्यूरोसाइंस और सकारात्मक मनोविज्ञान (Positive Psychology) में 'Mindset / Thought-Restructuring' का यह विश्व का प्राचीनतम और सर्वाधिक वैज्ञानिक साक्ष्य है।",
