      "translation": "हे दुःखों का नाश करने वाले भगवान रुद्र! अधर्म और पाप का शमन करने वाले आपके पावन क्रोध को हमारा बारंबार नमस्कार है। आपके तीक्ष्ण बाण को नमस्कार है। आपके पिनाक धनुष को नमस्कार हो और जगत का भरण-पोषण करने वाली आपकी दोनों दिव्य भुजाओं को हमारा नमस्कार हो। हे कैलास पर्वत पर विराजित होकर सुख का विस्तार करने वाले गिरिवासी महादेव! आपकी जो परम शांत, अघोर (अत्यंत कल्याणमयी) और अविद्या-पाप से रहित विशुद्ध तनु (स्वरूप) है, उस परम सुखदायिनी मूर्ति से आप हमारी ओर अनुग्रहपूर्वक दृष्टिपात करें और हमें आत्म-दर्शन प्रदान करें।"
