    "traditionsDifferences": "सामवेद के ८ ब्राह्मणों में यह सबसे बड़ा होने के कारण 'महाब्राह्मण' कहलाता है। इसके बाद का 'षड्विंश ब्राह्मण' इसका परिशिष्ट माना जाता है।",
