    "intro": "छान्दोग्य उपनिषद सामवेद की कौथुम शाखा का प्रधान उपनिषद है। इसमें ८ प्रपाठक हैं। सामवेद का प्रसिद्ध महावाक्य **'तत्त्वमसि' (That Thou Art)**, ॐकार उद्गीथ उपासना, शाण्डिल्य विद्या ('सर्वं खल्विदं ब्रह्म'), सत्यकाम जाबाल की सत्यनिष्ठा और महर्षि सनत्कुमार-नारद संवाद (भूमा विद्या) इसी उपनिषद में संगृहीत हैं।",
    "etymology": [
      {
        "term": "छान्दोग्य",
        "meaning": "छंदों (सामवेद के साम गान) से सम्बद्ध उपनिषद।"
      },
      {
        "term": "तत्त्वमसि",
        "meaning": "तत् + त्वम् + असि — 'वह (परम चैतन्य) तुम ही हो'।"
      },
      {
        "term": "तज्जलान्",
        "meaning": "तत् + ज + ल + अन् — जिससे यह जगत उत्पन्न होता है, जिसमें लीन होता है और जिससे श्वास लेता है।"
      }
    ],
    "shastricBase": "छान्दोग्य उपनिषद ६.८.७, ३.१४.१, शंकराचार्य भाष्य।",
    "sourceMeta": {
      "grantha": "सामवेद (Samaveda)",
      "shakha": "कौथुम एवं राणायनीय",
      "kanda": "८ प्रपाठक (१५४ खण्ड)",
      "rishi": "उद्दालक आरुणि, श्वेतकेतु, सनत्कुमार, शाण्डिल्य",
      "devata": "ॐकार उद्गीथ, ब्रह्म"
    },
    "primaryMantra": {
      "sanskrit": "ॐ इत्येतदक्षरमुद्गीथमुपासीत।\n\nसर्वं खल्विदं ब्रह्म तज्जलानिति शान्त उपासीत।\n\nस य एषोऽणिमैतदात्म्यमिदं सर्वं तत्सत्यं स आत्मा तत्त्वमसि श्वेतकेतो॥",
      "ref": "छान्दोग्य १.१.१, ३.१४.१, ६.८.७",
      "translation": "ॐ इस अविनाशी अक्षर की उद्गीथ के रूप में उपासना करें। यह संपूर्ण विश्व ब्रह्म ही है, उसी से उत्पन्न होता है, उसी में विलीन होता है। हे श्वेतकेतु! जो यह सूक्ष्म आत्मतत्व है, वही सत्य है, वही आत्मा है और 'वह तुम ही हो' (तत्त्वमसि)।"
    },
    "deitiesSymbols": "उद्गीथ (ॐकार, वाणी और साम का रस), शाण्डिल्य विद्या (हृदय में स्थित अंगुष्ठमात्र ब्रह्म), दहर विद्या (हृदय-कमल का सूक्ष्म आकाश), मधु विद्या (आदित्य रूपी अमृत)।",
    "traditionPlaces": "कुरु-पाञ्चाल, केकय जनपद (राजा अश्वपति) और नैमिषारण्य।",
    "vidhiUsage": "सामगान, उद्गीथोपासना, शाण्डिल्योपासना तथा संन्यास दीक्षा में 'तत्त्वमसि' महावाक्य का श्रवण।",
    "traditionsDifferences": "सामवेद की कौथुम और राणायनीय दोनों शाखाओं में यह ८ प्रपाठकों में सुरक्षित है।",
    "historyResearch": "सत्यकाम जाबाल और उद्दालक-श्वेतकेतु संवाद (मिट्टी और सोने के दृष्टांत) अद्वैत दर्शन के मूलाधार हैं। शोपेनहावर (Schopenhauer) ने उपनिषदों की दार्शनिक सर्वोच्चता को स्वीकार किया।",
