    "primaryMantra": {
      "sanskrit": "ॐ इत्येतदक्षरमिदँ सर्वं तस्योपव्याख्यानं भूतं भवद्भवविष्यदिति सर्वमोंकार एव...।\nसर्वं ह्येतद् ब्रह्मायमात्मा ब्रह्म सोऽयमात्मा चतुष्पात्॥१-२॥\n\nनान्तष्प्रज्ञं न बहिष्प्रज्ञं... प्रपञ्चोपशमं शान्तं शिवमद्वैतं चतुर्थं मन्यन्ते स आत्मा स विज्ञेयः॥७॥",
      "ref": "माण्डूक्योपनिषद् मंत्र १-२ एवं ७",
      "translation": "ॐ यह अक्षर ही सब कुछ है। भूत, वर्तमान और भविष्य सब ॐकार ही है। यह सब कुछ निश्चय ही ब्रह्म है। 'यह आत्मा ही ब्रह्म है' (अयमात्मा ब्रह्म)। वह जो न अंतःप्रज्ञ है, न बहिःप्रज्ञ है, समस्त प्रपंचों से रहित, शांत, कल्याणकारी (शिव) और अद्वैत है—वही तुरीय आत्मा है, वही जानने योग्य है।"
    },
    "deitiesSymbols": "ॐकार की चार मात्राएँ (अ = जाग्रत/वैश्वानर, उ = स्वप्न/तैजस, म = सुषुप्ति/प्राज्ञ, अमात्र = तुरीय/शुद्ध आत्मचैतन्य)।",
    "traditionPlaces": "अथर्ववेदीय शौनक परंपरा।",
    "vidhiUsage": "तुरीयावस्था की प्राप्ति हेतु नादब्रह्म और ॐकार की निरंतर मानसिक साधना।",
    "traditionsDifferences": "मुक्तिकोपनिषद (१.२६) में कहा गया है: 'माण्डूक्यमेकमेवालं मुमुक्षूणां विमुक्तये' (मुमुक्षुओं की मुक्ति के लिए अकेला माण्डूक्य उपनिषद ही पर्याप्त है)।",
    "historyResearch": "गौडपादाचार्य कृत 'माण्डूक्य कारिका' अद्वैत वेदांत का प्रथम व्यवस्थित दार्शनिक ग्रंथ है। आधुनिक क्वांटम भौतिकी में 'ऑब्जर्वर इफेक्ट' (Observer Effect) और चेतना के स्तरों के अध्ययन में माण्डूक्य के सिद्धांतों को प्रमुख स्थान मिला है।",
