    "shastricBase": "प्रश्नोपनिषद् का शास्त्रीय आधार अथर्ववेद पिप्पलाद संहिता, आदि शंकराचार्य कृत 'प्रश्नोपनिषद् भाष्य', आनन्दगिरि कृत 'टीका', छान्दोग्य उपनिषद् (काण्ड ५.१ - प्राण-संवाद), बृहदारण्यक उपनिषद् (काण्ड ६.१), तथा मुण्डक व माण्डूक्य उपनिषदों की वैदिक परंपरा में सुदृढ़ रूप से प्रतिष्ठित है।",
