        "sayanaBhashya": "आदि शंकराचार्य भाष्य: ब्रह्मविद्या प्राप्त करने हेतु पात्रता (अधिकार) की प्रथम शर्त है इन्द्रिय-संयम, अहंकार-शून्यता और गुरु-सेवा। पिप्पलाद ने शिष्यों की परीक्षा तथा अंतःकरण की शुद्धि हेतु एक वर्ष की अवधि निर्धारित की।"
