        "padapatha": "तस्मै । सः । ह॒ । उवाच । प्रजाऽकामः । वै । प्रजापतिः । सः । तपः । अतप्यत । सः । तपः । तप्त्वा । सः । मिथुनम् । उत्पादयते । रयिम् । च॒ । प्राणम् । च॒ ।",
