        "sanskrit": "तान् वरिष्ठः प्राण उवाच—मा मोहमापद्यथ, अहमेवैतत् पञ्चधाऽऽत्मानं प्रविभज्यैतद् बाणमवष्टभ्य विधारयामीति, तेऽश्रद्दधाना बभूवुः॥\nसोऽभिमानादूर्ध्वमुत्क्रमत इव, तस्मिन्नुत्क्रामत्यथेतरे सर्व एवोत्क्रामन्ते, तस्मिंश्च प्रतिष्ठमाने सर्व एव प्रतिष्ठन्ते...॥\nप्राणस्येदं वशे सर्वं त्रिदिवे यत्प्रतिष्ठितम्। मातेव पुत्रान् रक्षस्व श्रीश्च प्रज्ञां च विधेहि न इति॥",
