        "number": "४ (प्रश्नोपनिषद् ३.३-५ - तृतीय प्रश्न: प्राण की उत्पत्ति एवं शरीर में ५ स्थान)",
        "sanskrit": "तस्मै स होवाच—आत्मन एष प्राणो जायते। यथैषा पुरुषे छायैतस्मिन्नेतदाततं मनोकृतेनायात्यस्मिञ्शरीरे॥\nयथा सम्राडेवाधिकृतान् विनियुङ्क्ते—एतान् ग्रामानिति, एवमेवैष प्राण इतरान् प्राणान् पृथक् पृथगेव संनिधत्ते॥\nपायूपस्थेऽपानं चक्षुःश्रोत्रे मुखनासिकाभ्यां प्राणः स्वयं प्रतिष्ठिते मध्ये तु समानः...॥",
        "transliteration": "tasmai sa hovāca—ātmana eṣa prāṇo jāyate | yathaiṣā puruṣe chāyaitasminnetadātataṃ manokṛtenāyātyasmiñśarīre ||\nyathā samrāḍevādhikṛtān viniyuṅkte—etān grāmāniti, evamevaiṣa prāṇa itarān prāṇān pṛthak pṛthageva saṃnidhatte ||\npāyūpasthe'pānaṃ cakṣuḥśrotre mukhanāsikābhyāṃ prāṇaḥ svayaṃ pratiṣṭhite madhye tu samānaḥ... ||",
        "padapatha": "आत्मनः । एषः । प्राणः । जायते । यथा । एषा । पुरुषे । छाया । एतस्मिन् । एतत् । आततम् । मनःऽकृतेन । आयाति । अस्मिन् । शरीरे ।",
