        "translation": "कौसल्य आश्वलायन के प्रश्न पर पिप्पलाद ने कहा: यह प्राण परमात्मा (आत्मा) से उत्पन्न होता है। जैसे मनुष्य के शरीर से उसकी छाया अभिन्न रूप से जुड़ी रहती है, वैसे ही यह प्राण आत्मा पर फैला हुआ है। पूर्वजन्म के मन के संकल्पों और कर्मों के कारण यह इस शरीर में आता है। जैसे कोई सम्राट अधिकारियों को आदेश देकर अलग-अलग गांवों में नियुक्त करता है, वैसे ही मुख्य प्राण अन्य प्राणों को शरीर में नियुक्त करता है: अपान को पायु और उपस्थ में, प्राण स्वयं मुख और नासिका में, तथा मध्य (नाभि) में समान वायु को स्थापित करता है जो अन्न को पचाकर समभाव से बांटता है।",
