        "translation": "सौर्यायणि गार्ग्य के प्रश्न पर पिप्पलाद कहते हैं: जब इंद्रियाँ सो जाती हैं, तब यह मन रूपी देव स्वप्न में अपनी दिव्य महिमा का अनुभव करता है। जो कुछ देखा गया था उसे फिर देखता है, जो सुना था उसे फिर सुनता है, जो अनुभव किया था उसे पुनः जीता है। जो देखा नहीं, जो सुना नहीं, जो सत्य है और जो असत्य है—वह स्वयं ही सब कुछ बनकर सब देखता है। और सुषुप्ति में यह द्रष्टा, स्प्रष्टा, श्रोता, घ्राता, रसयिता, मन्ता, बोद्धा और कर्ता रूप 'विज्ञानात्मा पुरुष' उस परम अविनाशी अक्षर ब्रह्म में पूर्णतः प्रतिष्ठित होकर परम शांति पाता है।",
