        "sanskrit": "तस्मै स होवाच—एतद्वै सत्यकाम परं चापरं च ब्रह्म यदोङ्कारस्तस्माद्विद्वानेतेनैवायतनेनैकतरमन्वेति॥\nयः पुनरेतं त्रिमात्रेणोमित्येतेनैवाक्षरेण परं पुरुषमभिध्यायीत स तेजसि सूर्ये संपन्नः। यथा पादोदरस्त्वचा विनिर्मुच्यत एवं ह वै स पाप्मना विनिर्मुक्तः स सामभिरुन्नीयते ब्रह्मलोकं स एतस्माज्जीवघनात् परात्परं पुरिशयं पुरुषमीक्षते॥",
        "transliteration": "tasmai sa hovāca—etadvai satyakāma paraṃ cāparaṃ ca brahma yadoṅkārastasmādvidvānetenaivāyatanenaikataramanveti ||\nyaḥ punaretaṃ trimātreṇomityetenaivākṣareṇa paraṃ puruṣamabhidhyāyīta sa tejasi sūrye saṃpannaḥ | yathā pādodarastvacā vinirmucyata evaṃ ha vai sa pāpmanā vinirmuktaḥ sa sāmabhirunnīyate brahmalokaṃ sa etasmājjīvaghanāt parātparaṃ puriśayaṃ puruṣamīkṣate ||",
