        "translation": "सत्यकाम के प्रश्न पर पिप्पलाद ने कहा: हे सत्यकाम! यह ॐकार ही पर (निर्गुण) और अपर (सगुण) दोनों ब्रह्म का स्वरूप है। अतः ज्ञानी पुरुष इसी ॐकार के आश्रय से इनमें से किसी एक को प्राप्त करता है। जो केवल एक मात्रा 'अ' का ध्यान करता है, वह शीघ्र मनुष्य लोक में आता है; जो दो मात्राओं 'अ-उ' का ध्यान करता है, वह चंद्रलोक में जाता है; किंतु जो ॐकार की तीनों मात्राओं (अ, उ, म) से युक्त होकर परम पुरुष का ध्यान करता है, वह सूर्य-मंडल में पहुँचकर पापों से ऐसे मुक्त हो जाता है जैसे सर्प अपनी केंचुल उतार फेंकता है। सामवेद के मंत्र उसे ब्रह्मलोक ले जाते हैं और वह समस्त जीवों से परे हृदय में विराजित परात्पर पुरुष का साक्षात्कार करता है।",
        "englishTranslation": "Pippalada instructed Satyakama: The syllable Om is verily both the higher (attributeless) and lower (manifest) Brahman. One who meditates on Om with all three matras (A, U, M) merges into the solar radiance, sheds all sins like a serpent sloughing off its skin, and is led by the Sama hymns to the realm of Brahman, realizing the Supreme Purusha dwelling within the heart.",
        "sayanaBhashya": "शंकराचार्य भाष्य: ॐकार उपासना प्रस्थानत्रयी का केंद्रीय साधन है। अकार ऋग्वेद और जाग्रत अवस्था, उकार यजुर्वेद और स्वप्नावस्था, मकार सामवेद और सुषुप्ति अवस्था है। अखंड त्रिमात्र ॐकार तुरीय परब्रह्म का वाचक है।"
