        "sanskrit": "तस्मै स होवाच—इहैवान्तःशरीरे सोम्य स पुरुषो यस्मिन्नेताः षोडश कला प्रभवन्तीति॥\nस प्राणमसृजत प्राणाच्छ्रद्धां खं वायुं ज्योतिरापः पृथिवीन्द्रियं मनः। अन्नमन्नाद्वीर्यं तपो मन्त्राः कर्म लोका लोकेषु च नाम च॥\nस यथेमा नद्यः स्यन्दमानाः समुद्रायणाः समुद्रं प्राप्यास्तं गच्छन्ति भिद्येते तासां नामरूपे समुद्र इत्येवं प्रोच्यते। एवमेवास्य परिद्रष्टुरिमाः षोडश कलाः पुरुषायणाः पुरुषं प्राप्यास्तं गच्छन्ति भिद्येते तासां नामरूपे पुरुष इत्येवं प्रोच्यते स एषोऽकलोऽमृतो भवति॥",
        "transliteration": "tasmai sa hovāca—ihaivāntaḥśarīre somya sa puruṣo yasminnetāḥ ṣoḍaśa kalā prabhavantīti ||\nsa prāṇamasṛjata prāṇācchraddhāṃ khaṃ vāyuṃ jyotirāpaḥ pṛthivīndriyaṃ manaḥ | annamannādvīryaṃ tapo mantrāḥ karma lokā lokeṣu ca nāma ca ||\nsa yathemā nadyaḥ syandamānāḥ samudrāyaṇāḥ samudraṃ prāpyāstaṃ gacchanti bhidyete tāsāṃ nāmarūpe samudra ityevaṃ procyate | evamevāsya paridraṣṭurimāḥ ṣoḍaśa kalāḥ puruṣāyaṇāḥ puruṣaṃ prāpyāstaṃ gacchanti bhidyete tāsāṃ nāmarūpe puruṣa ityevaṃ procyate sa eṣo'kalo'mṛto bhavati ||",
