        "englishTranslation": "Pippalada concluded to Sukesha: That Person with sixteen parts dwells right here within this very body! From Him arose Prana, and from Prana came faith, space, air, fire, water, earth, the senses, mind, food, strength, austerity, mantras, rites, worlds, and in the worlds, names. And just as flowing rivers heading toward the ocean merge into the sea losing their individual names and forms and are simply called 'ocean', even so the sixteen parts of this observing seer merge into the Purusha, losing their names and forms, and are known only as Purusha. He becomes partless and immortal!",
