    "intro": "कौशिक सूत्र अथर्ववेद की शौनक शाखा का अत्यंत महत्त्वपूर्ण गृह्य एवं अनुष्ठान ग्रंथ है। इसके रचयिता महर्षि कौशिक हैं। इसमें १४ अध्याय और १४१ कंडिकाएँ हैं। यह केवल पारंपरिक १६ संस्कारों तक सीमित नहीं है, अपितु आयुर्वेद की मूल औषधियों (भैषज्य कर्माणि), विष-निवारण, ज्वर व व्याधि शांति, राष्ट्र-सुरक्षा, राज्याभिषेक (सावित्र उत्सव), तथा नकारात्मक ऊर्जा के शमन हेतु वैदिक शांति-पौष्टिक अनुष्ठानों का विश्वकोश है।",
