    "intro": "वैतान श्रौतसूत्र अथर्ववेद का एकमात्र उपलब्ध एवं अत्यंत प्रामाणिक श्रौतसूत्र है। इसमें कुल ८ अध्याय और ४३ कंडिकाएँ हैं। यह ग्रंथ दर्शपूर्णमास, चातुर्मास्य, पशुबंध, अग्निष्टोम, वाजपेय, राजसूय और अश्वमेध आदि महापर्वों में यज्ञ के सर्वोच्च संचालक 'ब्रह्मा' (Brahma Priest) और उसके सहायक 'ब्राह्मणाच्छंसी' के विशिष्ट कर्तव्यों, मौन निरीक्षण, तथा यज्ञीय त्रुटियों को सुधारने वाले 'व्याहृति प्रायश्चित्त' का सांगोपांग विधान प्रस्तुत करता है।",
